gdr.ValidationScript:
const runValidationScript = function () {
    const currentModel = Data.GetValue("ModelName__");
    if (!currentModel) {
        const splitWSResponse = Sys.Helpers.Batch.getWSResponse();
        if (splitWSResponse) {
            let lengthSplitState = Document.GetPageCount() - 1;
            if (splitWSResponse.batch)
                lengthSplitState = splitWSResponse.batch.length;
            Data.SetValue("ModelName__", splitWSResponse.ModelID);
            Data.SetValue("splitStateLength__", lengthSplitState);
            let nbPredictedPagesToMerge = 0;
            let nbPredictedPagesToSplit = 0;
            let nbPredictedPagesAsAttachment = 0;
            if (lengthSplitState < 1)
                lengthSplitState = Document.GetPageCount() - 1;
            const splitStateTabular = Sys.Helpers.Batch.buildTabularSplitState(splitWSResponse.splitstate, lengthSplitState);
            for (let i = 0; i < lengthSplitState; i++) {
                if (splitStateTabular[i] === 0)
                    nbPredictedPagesToMerge++;
                else if (splitStateTabular[i] === 1)
                    nbPredictedPagesToSplit++;
                else if (splitStateTabular[i] === 2)
                    nbPredictedPagesAsAttachment++;
            }
            Data.SetValue("nbPredictedPagesToMerge__", nbPredictedPagesToMerge);
            Data.SetValue("nbPredictedPagesToSplit__", nbPredictedPagesToSplit);
            Data.SetValue("nbPredictedPagesAsAttachment__", nbPredictedPagesAsAttachment);
        }
    }
};
runValidationScript();
//# sourceMappingURL=validationscript.js.map

gdr.ExtractionScript:
const runExtraction = function () {
    Sys.Helpers.TryCallFunction("Lib.AP.Customization.Extraction.OnBatchExtractionScriptBegin");
    // Set the subject of the form
    Data.SetValue("Subject", Language.Translate("_Received file: {0}", false, Document.GetName()));
    // Set the splitting recipient
    const nextProcessid = Process.GetNextProcessID();
    if (nextProcessid) {
        Data.SetValue("SplitToProcessId", nextProcessid);
        handleSplitOwner();
    }
    // Serialize the configuration on the record
    Sys.Parameters.GetInstance("P2P").Serialize();
    Sys.Parameters.GetInstance("AP").Serialize();
    handleSplitAndValidation();
    Sys.Helpers.TryCallFunction("Lib.AP.Customization.Extraction.OnBatchExtractionScriptEnd");
};
function handleSplitOwner() {
    if (Data.GetValue("OriginalJobID")) {
        setSplitToOwner(Users.GetUser(Data.GetValue("OwnerId")));
    }
    else {
        let specificVendorInvoiceOwner = Variable.GetValueAsString("VendorInvoiceOwner");
        if (specificVendorInvoiceOwner) {
            specificVendorInvoiceOwner = Lib.P2P.ResolveDemoLogin(specificVendorInvoiceOwner);
            Log.Info(`'VendorInvoiceOwner' variable set to '${specificVendorInvoiceOwner}', forwarding process and setting 'SplitToOwner' to this owner.`);
            Process.Forward(specificVendorInvoiceOwner);
            setSplitToOwner(Users.GetUser(specificVendorInvoiceOwner));
        }
        else {
            const nextProcessUser = Process.GetNextProcessUser();
            if (nextProcessUser) {
                setSplitToOwner(nextProcessUser);
            }
        }
    }
}
function handleSplitAndValidation() {
    const nPages = Document.GetPageCount();
    const nPagesMinimum = Sys.Helpers.TryCallFunction("Lib.AP.Customization.Extraction.DetermineMinimumPageCountToSplit") || 1;
    let isTxtFile = false;
    if (nPages > nPagesMinimum) {
        const processedDoc = Attach.GetProcessedDocument();
        const processedFile = processedDoc.GetInputFile();
        const ext = processedFile.GetExtension().toLowerCase();
        isTxtFile = ext === ".txt";
    }
    if (nPages <= nPagesMinimum || isTxtFile) {
        Log.Info(`${isTxtFile ? "Txt file" : "Single page"} - auto approve (pages=${nPages})`);
        // No split required
    }
    else {
        Log.Info(`Multiple pages - splitting required (pages=${nPages})`);
        Data.SetValue("Split", 1);
        Data.SetValue("NeedValidation", 1);
    }
}
function setSplitToOwner(user) {
    Data.SetValue("SplitToOwnerID", user.GetValue("FullDn"));
    Data.SetValue("SplitToOwnerPB", user.GetValue("OwnerPB"));
}
runExtraction();
//# sourceMappingURL=extractionscript.js.map

gdr.PostProcessingScript:
const addRecords = function (splitState, splitWSResponse, splitStateTabular) {
    let nbRecordAdded = 0;
    for (let i = 0; i < splitWSResponse.batch.length; i++) {
        if (splitStateTabular[i] < 3) {
            const inputData = splitWSResponse.batch[i];
            const validateData = {
                page_no: i + 1,
                split_state: splitStateTabular[i],
                batch_split_state: splitState
            };
            if (Sys.Helpers.Batch.createRecordForLearningStep(inputData, validateData, splitWSResponse.Model_Version, splitWSResponse.Model_Type)) {
                nbRecordAdded++;
            }
        }
    }
    Log.Info(`${nbRecordAdded} records added for the model ${splitWSResponse.Model_Version} associated to the document type ${splitWSResponse.Model_Type}`);
};
const runPostProcessing = function () {
    const splitWSResponse = Sys.Helpers.Batch.getWSResponse();
    if (splitWSResponse) {
        // Use ReadValue instead of Read because Read returns false when the feature has not been explicitly opted in
        // (i.e., no record exists in the database), whereas ReadValue returns the actual stored value.
        const batchSplittingV2Enabled = FeatureToggle.ReadValue("AllowMLBatchSplittingV2") !== "0";
        const generateUserActions = Variable.GetValueAsString("GenerateEmbeddingsForModelCreation") || "disable";
        const splitState = Data.GetValue("SplitState");
        const formState = Data.GetValue("State");
        let lengthSplitState = Document.GetPageCount() - 1;
        if (splitWSResponse.batch)
            lengthSplitState = splitWSResponse.batch.length;
        const splitStateTabular = Sys.Helpers.Batch.buildTabularSplitState(splitState, lengthSplitState);
        if ((batchSplittingV2Enabled || generateUserActions.toLowerCase() == "enable") && splitState && formState === 100) {
            const currentModelType = Variable.GetValueAsString("model_type") || "INVOICE";
            if (splitWSResponse.Model_Type === currentModelType) {
                addRecords(splitState, splitWSResponse, splitStateTabular);
            }
            else {
                Log.Warn(`The model type during prediction was ${splitWSResponse.Model_Type} whereas the current model type is ${currentModelType}`);
            }
        }
        let nbExpectedPagesToMerge = 0;
        let nbExpectedPagesToSplit = 0;
        let nbExpectedPagesAsAttachment = 0;
        for (let i = 0; i < lengthSplitState; i++) {
            if (splitStateTabular[i] < 3) {
                if (splitStateTabular[i] === 0)
                    nbExpectedPagesToMerge++;
                else if (splitStateTabular[i] === 1)
                    nbExpectedPagesToSplit++;
                else if (splitStateTabular[i] === 2)
                    nbExpectedPagesAsAttachment++;
            }
        }
        Data.SetValue("nbExpectedPagesToMerge__", nbExpectedPagesToMerge);
        Data.SetValue("nbExpectedPagesToSplit__", nbExpectedPagesToSplit);
        Data.SetValue("nbExpectedPagesAsAttachment__", nbExpectedPagesAsAttachment);
    }
};
runPostProcessing();
//# sourceMappingURL=postprocessingscript.js.map

